var n=`1069-hokkien-prawn-mee`;var t=`world-1069`;var s=`SG`;var a=`southeast-asia`;var o=4;var r=56;var m={en:`Hokkien Prawn Mee`,ua:`Хоккієн мі з креветками`};var l={en:`Hokkien Prawn Mee is a dish from Singapore prepared with pork bones, garlic, shrimp, pork belly. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Хоккієн мі з креветками, страва кухні країни Сінгапур, яку готують із таких продуктів: свинячі кістки, часник, креветка, свиняча грудинка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 24 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 24 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:24,i:[[`shrimp-stock`,900,`ml`],[`pork-bones`,350,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`garlic`,5,`clove`],[`shrimp`,340,`g`],[`pork-belly`,240,`g`],[`canola-oil`,40,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 7 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 7 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:7,i:[[`egg-noodles`,240,`g`],[`rice-vermicelli`,230,`g`],[`water`,950,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`fish-sauce`,28,`ml`],[`light-soy-sauce`,30,`ml`],[`water`,150,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 4 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 4 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:4,i:[[`chicken-egg`,3,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,2,`pcs`],[`chives`,70,`g`]]}];var u={slug:n,id:t,country:`SG`,region:a,servings:4,minutes:56,title:m,text:l,steps:g};export{s as country,u as default,t as id,r as minutes,a as region,o as servings,n as slug,g as steps,l as text,m as title};